// Pass 1: find max -> n moves
int mx = a[0];
for (int i = 1; i < n; i++)
    if (a[i] > mx) mx = a[i];

// Pass 2: sum -> n more moves
long long total = 0;
for (int i = 0; i < n; i++) total += a[i];
// Sequential: n + n = 2n moves. Fine.

// Nested: EVERY element against EVERY element -> n*n moves
for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
        if (a[i] + a[j] == 42) cout << "pair!";

